'use strict';
const $=id=>document.getElementById(id),$$=q=>[...document.querySelectorAll(q)];
const S={lang:'zh',tab:'studio',model:'tissue',layer:'conv_pw_11_relu',channel:7,rate:.012,steps:20,input:'training/probes/input.png',inputId:'nasa-independent',filename:'astronaut.png',sourceKey:'demoSource',source:'NASA / Eileen Collins / Public domain',width:128,height:128,originalWidth:512,originalHeight:512,frames:[],frame:0,current:null,records:[],db:null,models:new Map(),extractors:new Map(),activations:null,comparison:null,activationToken:0,busy:false,cancel:false,restart:false,completed:0,timer:null,status:{key:'ready'},heatStatus:{key:'recorded'},run:null,data:null,probes:null,preset:null,checkpointIndex:3,presenting:false};
try{S.lang=localStorage.getItem('dreams-language')||'zh';}catch{}if(!['zh','en'].includes(S.lang))S.lang='zh';
const T=k=>COPY[k]?.[S.lang==='en'?1:0]||(S.lang==='en'?'Translation unavailable':'翻译暂缺');const CODE='prd2-engine-v1';let toastTimer,paramTimer,inspectTimer;
function message(key,detail='',error=false){S.status={key,detail,error};renderStatus();}function heatMessage(key,detail=''){S.heatStatus={key,detail};$('activationStatus').textContent=T(key)+(detail?' · '+detail:'');}
function renderStatus(){$('status').textContent=T(S.status.key)+(S.status.detail?' · '+S.status.detail:'');$('status').classList.toggle('error',!!S.status.error);$('activationStatus').textContent=T(S.heatStatus.key)+(S.heatStatus.detail?' · '+S.heatStatus.detail:'');}
function toast(key){$('toast').textContent=T(key);$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
function modelURL(id){return id==='base'?'training/checkpoints/epoch-0/model.json':id==='tissue'?'training/checkpoints/epoch-8/model.json':`training/checkpoints/epoch-${id.replace('epoch','')}/model.json`;}
function epochFor(id){return id==='base'?0:id==='tissue'?8:Number(id.replace('epoch',''));}
function modelName(id){return id==='base'?T('baseModel'):id==='tissue'?T('tissueModel'):`PathMNIST · Epoch ${epochFor(id)}`;}
function header(){const recorded=S.tab==='training'||!(S.busy||S.inspectBusy||(S.tab==='channels'&&S.responseMode==='live')); $('globalStatus').textContent=T(recorded?'recorded':'live');$('version').textContent=S.tab==='training'?`MobileNet 0.25 · Epoch ${[0,2,4,8][S.checkpointIndex]}`:`MobileNet 0.25 · ${S.model==='base'?'ImageNet':`PathMNIST E${epochFor(S.model)}`}`;$('runtimeLabel').textContent=T(S.busy?'live':'recorded');}
function switchTab(tab){S.tab=tab;$$('.tab-panel').forEach(p=>p.hidden=p.id!==tab);$$('[data-tab]').forEach(b=>{b.classList.toggle('selected',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab);});header();if(tab==='channels'&&!S.activations)inspect();}
function selectors(){for(const select of $$('.model-select')){select.replaceChildren(...['base','epoch2','epoch4','tissue'].map(id=>new Option(modelName(id),id)));select.value=S.model;}for(const select of $$('.layer-select')){select.replaceChildren(...['conv_pw_5_relu','conv_pw_11_relu'].map(id=>new Option(id+' · '+(id==='conv_pw_5_relu'?(S.lang==='en'?'frozen control':'冻结对照'):(S.lang==='en'?'fine-tuning target':'微调目标')),id)));select.value=S.layer;}const count=S.layer==='conv_pw_5_relu'?64:128;for(const select of $$('.channel-select')){select.replaceChildren(new Option(T('allChannels'),'all'),...Array.from({length:count},(_,i)=>new Option(String(i),String(i))));select.value=S.channel===null?'all':String(S.channel);}$('strength').value=S.rate;$('strengthValue').textContent=S.rate.toFixed(3);$('iterations').value=S.steps;$('iterationsValue').textContent=S.steps;header();}
function translate(){document.documentElement.lang=S.lang==='en'?'en':'zh-CN';$$('[data-t]').forEach(e=>e.textContent=T(e.dataset.t));$('language').textContent=S.lang==='en'?'中文':'English';$('present').textContent=T(S.presenting?'exitPresent':'present');$('methodContent').innerHTML=METHODS[S.lang==='en'?1:0]+METHOD_LINKS;$$('.close-dialog').forEach(b=>b.setAttribute('aria-label',T('close')));$('timeline').setAttribute('aria-label',T('iteration'));selectors();renderStatus();renderInput();renderResult();renderRecords();renderTraining();renderActivation();renderPreset();$('play').setAttribute('aria-label',T(S.timer?'pause':'play'));if(S.current&&$('recordDialog').open)renderRecordDetails();}
function renderInput(){$$('.shared-input').forEach(img=>{img.src=S.input;img.alt=T('input');});$('inputName').textContent=S.filename;$('dimensions').textContent=`${S.width} × ${S.height}`;$('inputSource').textContent=(S.sourceKey?T(S.sourceKey):S.source)+` · ${S.originalWidth}×${S.originalHeight} → ${S.width}×${S.height}`;}
function renderResult(){const r=S.current;$('resultBadge').textContent=T(S.busy?'running':r?'actualResult':'pending');$('resultConfig').textContent=r?`${r.layer} / ch ${r.channel??'all'} / E${epochFor(r.modelId)}`:S.busy?`${S.active.layer} / ch ${S.active.channel??'all'}`:'—';if(S.frames.length)displayFrame(S.frame);for(const id of ['downloadPNG','record'])$(id).disabled=!r||S.busy;}
function stop(){clearInterval(S.timer);S.timer=null;$('play').textContent='▶';$('play').setAttribute('aria-label',T('play'));}
function displayFrame(index){if(!S.frames.length)return;S.frame=Math.max(0,Math.min(index,S.frames.length-1));const f=S.frames[S.frame];$('resultImage').src=f.url;$('resultImage').alt=T('dreamImage');$('timeline').max=S.frames.length-1;$('timeline').value=S.frame;$('frameLabel').textContent=`${f.step} / ${S.busy?S.active.steps:S.frames.at(-1).step}`;$('stepTag').textContent=`ITERATION ${String(f.step).padStart(3,'0')}`;$('resultState').textContent=`${f.step} ${T('iteration')}`;}
function normalizeRecord(r){return{...r,modelId:r.modelId||'base',checkpointId:r.checkpointId||'imagenet-original',channel:r.channel??null,datasetId:r.datasetId||'ImageNet',titleKey:r.titleKey||(r.builtin?'legacyTitle':null),requestedIterations:r.requestedIterations||r.iterations,completedIterations:r.completedIterations||r.iterations,codeVersion:r.codeVersion||'v1',inputId:r.inputId||'legacy-input'};}
function selectRecord(r){if(S.busy)return;stop();r=normalizeRecord(r);S.current=r;Object.assign(S,{model:r.modelId,layer:r.layer,channel:r.channel,rate:r.stepSize,steps:r.iterations,input:r.original,inputId:r.inputId,filename:r.filename,source:r.source,sourceKey:Object.hasOwn(r,'sourceKey')?r.sourceKey:(r.builtin?'demoSource':null),width:r.width,height:r.height,originalWidth:r.originalWidth||r.width,originalHeight:r.originalHeight||r.height,frames:r.frames,frame:r.frames.length-1});S.activations=null;S.comparison=null;selectors();renderInput();renderResult();renderRecords();message('ready');queueInspect();}
function recordTitle(r){return r.titleKey?T(r.titleKey):r.title||T('untitled');}
function renderRecords(){const list=$('records');list.replaceChildren();for(const r of S.records){const b=document.createElement('button');b.className='record-card'+(S.current?.id===r.id?' selected':'');b.disabled=S.busy;const img=document.createElement('img');img.className='record-image';img.src=r.frames.at(-1).url;img.alt=recordTitle(r);img.loading='lazy';const info=document.createElement('div');info.className='record-info';const title=document.createElement('h3');title.textContent=recordTitle(r);const detail=document.createElement('p');detail.textContent=`${r.modelId||'base'} · ${r.layer} · ch ${r.channel??'all'} · ${r.iterations}`;info.append(title,detail);b.append(img,info);b.onclick=()=>{selectRecord(r);switchTab('studio');$('studio').scrollIntoView({behavior:'smooth'});};list.append(b);}const b=document.createElement('button');b.className='new-record';b.disabled=S.busy;const plus=document.createElement('b'),title=document.createElement('span'),hint=document.createElement('small');plus.textContent='＋';title.textContent=T('newDream');hint.textContent=T('newDreamHelp');b.append(plus,title,hint);b.onclick=()=>$('fileInput').click();list.append(b);}
async function database(){return new Promise((resolve,reject)=>{const r=indexedDB.open('neural-dreams-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('records',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function dbAll(){return new Promise((resolve,reject)=>{const r=S.db.transaction('records').objectStore('records').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function persist(r){if(r.builtin)return;if(!S.db){toast('errorStorage');return;}return new Promise(resolve=>{const tx=S.db.transaction('records','readwrite');tx.objectStore('records').put(r);tx.oncomplete=resolve;tx.onerror=()=>{toast('errorStorage');resolve();};});}
function imgLoad(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('errorImage'));i.src=src;});}
async function upload(file){if(!file)return;if(S.busy){toast('stopForUpload');return;}if(!['image/png','image/jpeg'].includes(file.type)){toast('errorType');return;}if(file.size>20*1024*1024){toast('errorSize');return;}const url=URL.createObjectURL(file);try{const img=await imgLoad(url);if(Math.min(img.width,img.height)<32||Math.max(img.width/img.height,img.height/img.width)>8||img.width*img.height>5e7)throw new Error('errorSize');const k=Math.min(1,256/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*k);canvas.height=Math.round(img.height*k);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);stop();Object.assign(S,{input:canvas.toDataURL('image/png'),inputId:crypto.randomUUID(),filename:file.name,sourceKey:'userSource',source:'User upload; source/license pending',width:canvas.width,height:canvas.height,originalWidth:img.width,originalHeight:img.height,current:null,activations:null,comparison:null});S.frames=[{step:0,url:S.input}];S.frame=0;renderInput();renderResult();renderRecords();message('inputReady');queueInspect();}catch(e){toast(COPY[e.message]?e.message:'errorImage');}finally{URL.revokeObjectURL(url);$('fileInput').value='';}}
let backendPromise;async function backend(){if(!backendPromise)backendPromise=(async()=>{try{await tf.setBackend('webgl');}catch{await tf.setBackend('cpu');}await tf.ready();})();return backendPromise;}
async function model(id){await backend();if(!S.models.has(id)){const promise=tf.loadLayersModel(modelURL(id)).then(m=>{m.trainable=false;return m;}).catch(e=>{S.models.delete(id);throw e;});S.models.set(id,promise);}return S.models.get(id);}
async function extractor(id,layer){const key=id+'/'+layer;if(!S.extractors.has(key))S.extractors.set(key,model(id).then(m=>DreamEngine.extractor(tf,m,layer)).catch(e=>{S.extractors.delete(key);throw e;}));return S.extractors.get(key);}
async function inputTensor(src){const img=await imgLoad(src);return tf.tidy(()=>tf.browser.fromPixels(img).toFloat().div(127.5).sub(1).expandDims());}
function drawMap(canvas,map){canvas.width=map.width;canvas.height=map.height;canvas.getContext('2d').putImageData(new ImageData(DreamEngine.colors(map),map.width,map.height),0,0);}
function renderActivation(){if(!S.activations)return;const ch=S.channel??0,m=DreamEngine.map(S.activations,ch);drawMap($('selectedHeat'),m);drawMap($('miniHeat'),m);$('heatRange').textContent=`${S.layer} / ch ${ch} · ${T('range')}: ${m.min.toFixed(4)}–${m.max.toFixed(4)} · ${m.width}×${m.height}`;if(S.comparison){const c=DreamEngine.map(S.comparison,ch);drawMap($('comparisonHeat'),c);$('comparisonRange').textContent=`${modelName(S.model==='base'?'tissue':'base')} · ch ${ch} · ${c.min.toFixed(4)}–${c.max.toFixed(4)}`;}const c=S.activations.shape[2],sums=Array(c).fill(0);for(let i=0;i<S.activations.data.length;i++)sums[i%c]+=S.activations.data[i];const selected=Array.from({length:c},(_,i)=>i).sort((a,b)=>sums[b]-sums[a]).slice(0,12);if(!selected.includes(ch))selected[11]=ch;const grid=$('channelGrid');grid.replaceChildren();for(const channel of selected){const b=document.createElement('button');b.className='channel-tile'+(channel===ch?' selected':'');b.dataset.channel=channel;const canvas=document.createElement('canvas');drawMap(canvas,DreamEngine.map(S.activations,channel));const label=document.createElement('span');label.textContent=`ch ${channel} · μ ${(sums[channel]/(S.activations.shape[0]*S.activations.shape[1])).toFixed(3)}`;b.append(canvas,label);b.onclick=()=>changeParam('channel',channel);grid.append(b);}if(S.channel===null)heatMessage('fullLayerPreview');}
function queueInspect(){clearTimeout(inspectTimer);S.activationToken++;inspectTimer=setTimeout(inspect,300);}
async function inspect(){const token=++S.activationToken,id=S.model,layer=S.layer,input=S.input;S.inspectBusy=true;header();heatMessage('computingResponse');let x;try{const cached=S.probes?.activations?.[id]?.[layer];if(input==='training/probes/input.png'&&cached){S.activations=cached;S.comparison=S.probes.activations[id==='base'?'tissue':'base'][layer];if(token===S.activationToken){S.responseMode='recorded';heatMessage('recorded');renderActivation();}return;}x=await inputTensor(input);const a=await extractor(id,layer),b=await extractor(id==='base'?'tissue':'base',layer);const primary=await DreamEngine.inspect(tf,a,x),secondary=await DreamEngine.inspect(tf,b,x);if(token!==S.activationToken)return;S.activations=primary;S.comparison=secondary;S.responseMode='live';heatMessage('responseReady');renderActivation();}catch(e){console.error(e);if(token===S.activationToken)heatMessage('responseFallback');}finally{x?.dispose();if(token===S.activationToken){S.inspectBusy=false;header();}}}
function changeParam(key,value){S[key]=value;if(key==='layer'&&S.channel>=64)S.channel=0;selectors();if(['model','layer'].includes(key)){S.activations=null;S.comparison=null;queueInspect();}else if(key==='channel')renderActivation();if(S.busy){S.cancel=true;S.restart=true;message('restarting');}else message('updatedParams');}
function busy(on){S.busy=on;$('generate').disabled=on;$('cancel').hidden=!on;$('progress').hidden=!on;$$('.upload,#demo,#fileInput').forEach(b=>b.disabled=on);renderRecords();renderResult();header();}
async function tensorPNG(x){const t=tf.tidy(()=>x.squeeze().add(1).mul(127.5).clipByValue(0,255).cast('int32'));try{const c=document.createElement('canvas');await tf.browser.toPixels(t,c);return c.toDataURL('image/png');}finally{t.dispose();}}
async function generate(){if(S.busy)return;stop();clearTimeout(paramTimer);S.cancel=false;S.restart=false;const p={model:S.model,layer:S.layer,channel:S.channel,rate:S.rate,steps:S.steps,input:S.input,inputId:S.inputId,filename:S.filename,source:S.source,sourceKey:S.sourceKey,width:S.width,height:S.height,originalWidth:S.originalWidth,originalHeight:S.originalHeight};S.active=p;const previous=S.current;busy(true);S.completed=0;message('loadingModel');$('progressBar').style.width='0%';let x;const started=performance.now();try{const m=await extractor(p.model,p.layer);x=await inputTensor(p.input);if(S.cancel)throw new Error('cancelled');S.frames=[{step:0,url:p.input}];S.frame=0;displayFrame(0);for(let i=1;i<=p.steps;i++){if(S.cancel)throw new Error('cancelled');const next=DreamEngine.step(tf,m,x,p.rate,p.channel);x.dispose();x=next;S.completed=i;if(i%2===0||i===p.steps){S.frames.push({step:i,url:await tensorPNG(x)});displayFrame(S.frames.length-1);}message('generating',`${i}/${p.steps} · ${((performance.now()-started)/1000).toFixed(1)}s`);$('progressBar').style.width=`${i/p.steps*100}%`;await tf.nextFrame();}if(S.cancel)throw new Error('cancelled');const cp=S.run.checkpoints.find(c=>c.epoch===epochFor(p.model));const record={id:'run-'+crypto.randomUUID(),title:T('untitled'),titleKey:'untitled',modelId:p.model,model:'MobileNet V1 0.25',checkpointId:cp.id,checkpointSHA256:cp.weightsSHA256,datasetId:p.model==='base'?'ImageNet':S.data.id,trainingDatasetLicense:p.model==='base'?'ImageNet pretrained weights / Apache 2.0':'CC BY 4.0',layer:p.layer,channel:p.channel,stepSize:p.rate,iterations:p.steps,requestedIterations:p.steps,completedIterations:p.steps,original:p.input,inputId:p.inputId,filename:p.filename,source:p.source,sourceKey:p.sourceKey,width:p.width,height:p.height,originalWidth:p.originalWidth,originalHeight:p.originalHeight,frames:[...S.frames],createdAt:new Date().toISOString(),elapsedMs:Math.round(performance.now()-started),codeVersion:CODE,engine:'TensorFlow.js 4.22.0 / '+tf.getBackend(),objective:'mean activation / RMS-normalized gradient ascent',crop:false,restartPolicy:'cancel and restart from original on parameter change'};S.records.push(record);await persist(record);S.current=record;message('complete');}catch(e){console.error(e);S.current=previous;if(previous){S.frames=previous.frames;S.frame=S.frames.length-1;}else{S.frames=[{step:0,url:S.input}];S.frame=0;}message(S.cancel?'cancelled':'errorCompute','',!S.cancel);}finally{x?.dispose();const restart=S.restart;busy(false);if(restart){S.restart=false;message('restarting');paramTimer=setTimeout(generate,300);}}}
function safeName(s){return s.replace(/[\\/:*?"<>|]/g,'_').slice(0,80)||'Dream';}function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function metadata(r){const{frames,original,...meta}=r;return{...meta,title:recordTitle(r),original:'original.png',final:'final.png',frames:frames.map(f=>({step:f.step,file:`frames/step-${String(f.step).padStart(3,'0')}.png`})),imageOptimization:'Fixed network weights; only input pixels change.',datasetAttribution:S.data?.attribution,datasetSource:S.data?.url,groupArtifactStatus:r.builtin?'technical example, not group-curated':'user authored; group curation to be confirmed'};}
function renderRecordDetails(){$('recordDetails').textContent=JSON.stringify(metadata(S.current),null,2);}
function openRecord(){const r=S.current;if(!r)return;$('artTitle').value=recordTitle(r);$('artSource').value=r.source||'';$('artNote').value=r.note||'';$('scientistNote').value=r.scientistNote||'';$('artistNote').value=r.artistNote||'';$('miro').value=r.miro||'';renderRecordDetails();$('recordDialog').showModal();}
function saveNotes(){const r=S.current;if(!r)return;r.title=$('artTitle').value.trim()||T('untitled');r.titleKey=null;r.source=$('artSource').value.trim()||T('userSource');r.sourceKey=null;r.note=$('artNote').value;r.scientistNote=$('scientistNote').value;r.artistNote=$('artistNote').value;r.miro=$('miro').value;S.source=r.source;S.sourceKey=null;renderInput();const idx=S.records.findIndex(x=>x.id===r.id);if(idx>=0)S.records[idx]=r;persist(r);renderRecords();renderRecordDetails();}
async function exportPack(){if(!S.current)return;saveNotes();$('exportZIP').disabled=true;try{const r=S.current,files=await Promise.all([{name:'original.png',url:r.original},{name:'final.png',url:r.frames.at(-1).url},...r.frames.map(f=>({name:`frames/step-${String(f.step).padStart(3,'0')}.png`,url:f.url}))].map(async f=>{const res=await fetch(f.url);if(!res.ok)throw new Error();return{name:f.name,data:new Uint8Array(await res.arrayBuffer())};}));files.push({name:'record.json',data:JSON.stringify(metadata(r),null,2)},{name:'dataset-card.json',data:JSON.stringify(S.data,null,2)},{name:'training-run.json',data:JSON.stringify(S.run,null,2)},{name:'CURATION.md',data:`# ${recordTitle(r)}\n\n${T('artSource')}: ${r.source}\n\n${T('selectionNote')}: ${r.note||T('notAvailable')}\n\n${T('scientist')}: ${r.scientistNote||T('notAvailable')}\n\n${T('artist')}: ${r.artistNote||T('notAvailable')}\n\nMiro: ${r.miro||T('notAvailable')}\n\n${T('noGroupWork')}\n\n${T('footerStatement')}`});download(makeZip(files),safeName(recordTitle(r))+'.zip');toast('exported');}catch{toast('errorExport');}finally{$('exportZIP').disabled=false;}}
function facts(id,rows){$(id).replaceChildren();for(const[k,v]of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=T(k);dd.textContent=v;$(id).append(dt,dd);}}
function renderTraining(){if(!S.run)return;const r=S.run,d=S.data;facts('dataFacts',[['trainingCount',`${d.splits.train.count} / ${d.splits.val.count} / ${d.splits.test.count}`],['license',d.license],['datasetVersion','MedMNIST v2 · 28px'],['seed',d.seed],['preprocessing',T('preprocessValue')],['splitNote',T('splitValue')]]);facts('modelFacts',[['objective',T('objectiveValue')],['settings',`Adam · LR ${r.learningRate} · batch ${r.batchSize} · ${r.epochs} epochs`],['device',r.device],['date',new Date(r.completedAt).toLocaleDateString(S.lang==='en'?'en-GB':'zh-CN')],['testAccuracy',`${(r.test.accuracy*100).toFixed(1)}% · ${T('notClinical')}`]]);const logs=r.logs,max=Math.ceil(Math.max(...logs.flatMap(l=>[l.trainLoss,l.valLoss]))),x=e=>65+e/8*860,y=v=>180-v/max*145;let svg='';for(let i=0;i<=4;i++){const v=max*i/4;svg+=`<line x1="65" y1="${y(v)}" x2="925" y2="${y(v)}" stroke="#34422b"/><text x="15" y="${y(v)+4}" fill="#8a9e78" font-size="12">${v.toFixed(1)}</text>`;}for(let e=0;e<=8;e++)svg+=`<text x="${x(e)}" y="205" fill="#8a9e78" font-size="12">${e}</text>`;for(const[key,color]of[['trainLoss','#cfef9f'],['valLoss','#cfabed']]){svg+=`<polyline points="${logs.map(l=>`${x(l.epoch)},${y(l[key])}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5"/>`;for(const l of logs)svg+=`<circle cx="${x(l.epoch)}" cy="${y(l[key])}" r="3" fill="${color}"/>`;}svg+=`<text x="12" y="15" fill="#b2c69e" font-size="12">${S.lang==='en'?'Loss':'损失'}</text><text x="866" y="226" fill="#b2c69e" font-size="12">Epoch</text>`;$('lossChart').innerHTML=svg;$('lossChart').setAttribute('aria-label',T('metricsTitle'));$('trainingDetails').textContent=T('technicalRecord')+'\n'+JSON.stringify(r,null,2);renderCheckpoint();}
function renderCheckpoint(){if(!S.probes||!S.run)return;const cp=S.run.checkpoints[S.checkpointIndex],p=S.probes.checkpoints.find(x=>x.epoch===cp.epoch),log=S.run.logs.find(x=>x.epoch===cp.epoch);$('checkpointName').textContent=`Epoch ${cp.epoch}`;$('checkpointModel').href=cp.url;$('checkpointWeights').href=cp.url.replace('model.json','weights.bin');$('checkpointMetrics').textContent=`${T('trainLoss')}: ${log.trainLoss.toFixed(4)} · ${T('valLoss')}: ${log.valLoss.toFixed(4)} · ${T('validationAccuracy')}: ${(log.valAccuracy*100).toFixed(1)}% · ${T('steps')}: ${log.step}`;$('checkpointHeat').src=p.heat;$('checkpointDream').src=p.final;$('checkpointRange').textContent=`conv_pw_11_relu / ch ${S.probes.channel} · ${T('range')}: ${p.min.toFixed(4)}–${p.max.toFixed(4)} · min–max → [0,1]`;$('checkpointConfig').textContent=`${T('fixedConfig')}: ch ${S.probes.channel} · 0.012 × 20 · 128×128 · Epoch ${cp.epoch}`;header();}
function renderPreset(){if(!S.preset)return;const p=S.preset;const out={id:p.id,modelId:p.modelId,checkpointId:p.checkpointId,layer:p.layer,channel:p.channel,stepSize:p.stepSize,iterations:p.iterations,selectionReason:p.selectionReason[S.lang],failureObservation:p.failureObservation[S.lang],probes:p.tests};$('presetDetails').textContent=JSON.stringify(out,null,2);const gallery=$('probeGallery');gallery.replaceChildren();for(const test of p.tests){const item=document.createElement('article'),label=document.createElement('p');label.textContent=test.input+(test.isFailureProbe?' · '+(S.lang==='en'?'failure probe':'失败观察'):'');for(const src of [test.original,test.output]){const img=document.createElement('img');img.src=src;img.alt=test.input;item.append(img);}item.append(label);gallery.append(item);}}
$$('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('language').onclick=()=>{S.lang=S.lang==='zh'?'en':'zh';try{localStorage.setItem('dreams-language',S.lang);}catch{}translate();};$('present').onclick=()=>{S.presenting=!S.presenting;document.body.classList.toggle('presenting',S.presenting);$('present').textContent=T(S.presenting?'exitPresent':'present');window.scrollTo(0,0);};
$$('.model-select').forEach(s=>s.onchange=()=>changeParam('model',s.value));$$('.layer-select').forEach(s=>s.onchange=()=>changeParam('layer',s.value));$$('.channel-select').forEach(s=>s.onchange=()=>changeParam('channel',s.value==='all'?null:+s.value));$('strength').oninput=e=>changeParam('rate',+e.target.value);$('iterations').oninput=e=>changeParam('steps',+e.target.value);$('inspect').onclick=inspect;$('goChannels').onclick=()=>switchTab('channels');
$$('.upload').forEach(b=>b.onclick=()=>$('fileInput').click());$('fileInput').onchange=e=>upload(e.target.files[0]);$('generate').onclick=generate;$('cancel').onclick=()=>{clearTimeout(paramTimer);S.cancel=true;S.restart=false;message('cancelled');};$('demo').onclick=()=>{const r=S.records.find(x=>x.builtin&&x.modelId===S.model)||S.records.find(x=>x.builtin);if(r)selectRecord(r);};$('play').onclick=()=>{if(S.timer){stop();return;}if(S.frames.length<2){toast('needFrames');return;}if(S.frame===S.frames.length-1)displayFrame(0);$('play').textContent='Ⅱ';$('play').setAttribute('aria-label',T('pause'));S.timer=setInterval(()=>{if(S.frame===S.frames.length-1)stop();else displayFrame(S.frame+1);},500);};$('timeline').oninput=e=>{stop();displayFrame(+e.target.value);};$('resetFrame').onclick=()=>{stop();displayFrame(0);};
$('checkpoint').oninput=e=>{S.checkpointIndex=+e.target.value;renderCheckpoint();};$('applyPreset').onclick=()=>{if(!S.preset)return;for(const[k,v]of Object.entries({model:S.preset.modelId,layer:S.preset.layer,channel:S.preset.channel,rate:S.preset.stepSize,steps:S.preset.iterations}))changeParam(k,v);switchTab('studio');};$('record').onclick=openRecord;$('saveNotes').onclick=()=>{saveNotes();toast(S.current.builtin?'noteSavedExample':'saved');};$('exportJSON').onclick=()=>{saveNotes();download(new Blob([JSON.stringify(metadata(S.current),null,2)],{type:'application/json'}),safeName(recordTitle(S.current))+'.json');};$('exportZIP').onclick=exportPack;$('downloadPNG').onclick=async()=>{try{if(!S.current)return;const r=await fetch(S.current.frames.at(-1).url);if(!r.ok)throw new Error();download(await r.blob(),safeName(recordTitle(S.current))+'.png');}catch{toast('errorExport');}};$('downloadTraining').onclick=()=>download(new Blob([JSON.stringify({dataset:S.data,training:S.run,preset:S.preset},null,2)],{type:'application/json'}),'training-records.json');
for(const id of ['methods','methodFooter'])$(id).onclick=()=>$('methodDialog').showModal();$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.presenting){S.presenting=false;document.body.classList.remove('presenting');$('present').textContent=T('present');}});
async function getJSON(url){const r=await fetch(url);if(!r.ok)throw new Error(url);return r.json();}
(async()=>{translate();try{[S.run,S.data,S.probes,S.preset]=await Promise.all([getJSON('training/run.json'),getJSON('training/dataset.json'),getJSON('training/probes/manifest.json'),getJSON('training/preset.json')]);const examples=await getJSON('training/probes/records.json');S.records=examples.map(r=>({...r,builtin:true}));try{S.db=await database();S.records.push(...(await dbAll()).map(normalizeRecord));}catch{toast('errorStorage');}renderTraining();renderPreset();selectRecord(S.records.find(r=>r.modelId==='tissue')||S.records[0]);}catch(e){console.error(e);message('errorLoad','',true);renderRecords();}})();
